package main

import (
	"fmt"
	"maps"
	"slices"
	"strings"

	"github.com/agrigoryan/quadit/internal/core"
)

// pushSource is the web app's dictionary part holding what a notification
// outside the app says an inbox item is (core.NoteHeadlines), one key per
// type: "push.<type>". The web app words the desktop app's notifications
// with it, so they say what a push says.
func pushSource() string {
	var b strings.Builder
	b.WriteString(`// Code generated by "make generate" (cmd/webtypes) from the server's
// core.NoteHeadlines (internal/core/inbox.go). DO NOT EDIT.
//
// What a notification outside the app (a push, the desktop app's) says an
// inbox item is, by its type: {who} is the actor's name, {title} the item's.

export const push = {
`)
	for _, noteType := range slices.Sorted(maps.Keys(core.NoteHeadlines)) {
		fmt.Fprintf(&b, "  %q: %q,\n", "push."+noteType, core.NoteHeadlines[noteType])
	}
	b.WriteString("};\n")
	return b.String()
}
